#!/bin/bash
# Uninstall script for JetBrains PhpStorm
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling JetBrains PhpStorm..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping JetBrains PhpStorm if running..."
pkill -f "JetBrains PhpStorm" 2>/dev/null || true

# Kill application with bundle ID com.jetbrains.PhpStorm if running
echo "Stopping application with bundle ID com.jetbrains.PhpStorm if running..."
killall -9 "com.jetbrains.PhpStorm" 2>/dev/null || true

# Remove /Applications/PhpStorm.app
echo "Removing /Applications/PhpStorm.app..."
if [ -d "/Applications/PhpStorm.app" ]; then
    rm -rf "/Applications/PhpStorm.app" 2>/dev/null || true
elif [ -f "/Applications/PhpStorm.app" ]; then
    rm -f "/Applications/PhpStorm.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/JetBrains/consentOptions
echo "Removing $HOME/Library/Application Support/JetBrains/consentOptions..."
if [ -d "$HOME/Library/Application Support/JetBrains/consentOptions" ]; then
    rm -rf "$HOME/Library/Application Support/JetBrains/consentOptions" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/JetBrains/consentOptions" ]; then
    rm -f "$HOME/Library/Application Support/JetBrains/consentOptions" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/JetBrains/PhpStorm2026.2
echo "Removing $HOME/Library/Application Support/JetBrains/PhpStorm2026.2..."
if [ -d "$HOME/Library/Application Support/JetBrains/PhpStorm2026.2" ]; then
