fi

# Remove $HOME/Library/Caches/JetBrains/PhpStorm2026.2
echo "Removing $HOME/Library/Caches/JetBrains/PhpStorm2026.2..."
if [ -d "$HOME/Library/Caches/JetBrains/PhpStorm2026.2" ]; then
    rm -rf "$HOME/Library/Caches/JetBrains/PhpStorm2026.2" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/JetBrains/PhpStorm2026.2" ]; then
    rm -f "$HOME/Library/Caches/JetBrains/PhpStorm2026.2" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/JetBrains/PhpStorm2026.2
echo "Removing $HOME/Library/Logs/JetBrains/PhpStorm2026.2..."
if [ -d "$HOME/Library/Logs/JetBrains/PhpStorm2026.2" ]; then
    rm -rf "$HOME/Library/Logs/JetBrains/PhpStorm2026.2" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/JetBrains/PhpStorm2026.2" ]; then
    rm -f "$HOME/Library/Logs/JetBrains/PhpStorm2026.2" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.jetbrains.PhpStorm.plist
echo "Removing $HOME/Library/Preferences/com.jetbrains.PhpStorm.plist..."
if [ -d "$HOME/Library/Preferences/com.jetbrains.PhpStorm.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.jetbrains.PhpStorm.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.jetbrains.PhpStorm.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.jetbrains.PhpStorm.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/jetbrains.jetprofile.asset.plist
echo "Removing $HOME/Library/Preferences/jetbrains.jetprofile.asset.plist..."
if [ -d "$HOME/Library/Preferences/jetbrains.jetprofile.asset.plist" ]; then
    rm -rf "$HOME/Library/Preferences/jetbrains.jetprofile.asset.plist" 2>/dev/null || true
